<script setup>
import {inject,onMounted,reactive,ref} from 'vue';
import {consoleKey} from '../composables/useConsole';
const c=inject(consoleKey),filters=reactive({start:'',end:'',provider:''}),data=ref(null),error=ref(''),busy=ref(false);
async function load(){busy.value=true;error.value='';try{data.value=await c.api('usage-scopes?'+new URLSearchParams(filters));}catch(e){error.value=e.message;}finally{busy.value=false;}}onMounted(load);
</script>
<template><section class="card panel"><h2>群聊与成员消耗排名</h2><p class="muted">按群聊、私聊和系统任务记录。金额为本地归属估算，不用于拆分官方固定基准；历史缺少明细的调用只能补录 Token 与次数。</p><form class="scope-filters" @submit.prevent="load"><label>开始日期<input v-model="filters.start" type="date"></label><label>结束日期<input v-model="filters.end" type="date"></label><label>API<select v-model="filters.provider"><option value="">全部渠道</option><option value="deepseek">DeepSeek</option><option value="openai">OpenAI</option><option value="kimi">Kimi</option></select></label><button :disabled="busy">查询排名</button></form><p v-if="error" class="error-text">{{error}}</p><template v-if="data"><p class="muted">记录 {{data.totals.calls}} 次模型请求 · {{data.totals.tokens.toLocaleString()}} Tokens · 工具 {{data.totals.toolCalls}} 次 · 归属估算 ¥{{data.totals.totalCost.toFixed(4)}}</p><div class="table-wrap"><table><thead><tr><th>会话</th><th>模型请求</th><th>工具</th><th>Tokens</th><th>估算费用</th></tr></thead><tbody><tr v-for="row in data.scopes" :key="row.kind+row.id"><td>{{row.kind==='group'?'群聊':row.kind==='private'?'私聊':'系统'}} · {{row.name||row.id}}</td><td>{{row.calls}}</td><td>{{row.toolCalls}}</td><td>{{row.tokens.toLocaleString()}}</td><td>¥{{row.totalCost.toFixed(4)}}</td></tr></tbody></table></div><details><summary>成员消耗排名（前 200 名）</summary><div class="table-wrap"><table><thead><tr><th>成员 / QQ</th><th>模型请求</th><th>Tokens</th><th>估算费用</th></tr></thead><tbody><tr v-for="row in data.users" :key="row.userId"><td>{{row.name}} · {{row.userId}}</td><td>{{row.calls}}</td><td>{{row.tokens.toLocaleString()}}</td><td>¥{{row.totalCost.toFixed(4)}}</td></tr></tbody></table></div></details><p v-if="!data.scopes.length" class="muted">暂无归属统计。</p></template></section></template>
<style scoped>.scope-filters{display:flex;gap:12px;flex-wrap:wrap;align-items:end}.scope-filters label{flex:1 1 160px}</style>
